/// Type of communication or preparation draft.
enum DraftType {
  email('Email Draft'),
  whatsapp('WhatsApp / Message'),
  sms('SMS'),
  meetingBriefing('Meeting Briefing');

  final String label;
  const DraftType(this.label);
}

/// Status of the draft according to the permission levels:
/// 1. Suggest -> 2. Prepare draft -> 3. Ask for approval -> 4. Execute / Send.
enum DraftStatus {
  draft('Draft'),
  approved('Approved'),
  rejected('Rejected'),
  sent('Completed / Sent');

  final String label;
  const DraftStatus(this.label);
}

/// An action draft generated by the assistant for the user's explicit review.
class ActionDraft {
  final int? id;
  final DraftType type;
  final String title;
  final String? recipientName;
  final String? recipientContact;
  final String? subject;
  final String body;
  final DraftStatus status;
  final int? commitmentId;
  final int? contactId;
  final DateTime createdAt;
  final DateTime updatedAt;

  ActionDraft({
    this.id,
    required this.type,
    required this.title,
    this.recipientName,
    this.recipientContact,
    this.subject,
    required this.body,
    this.status = DraftStatus.draft,
    this.commitmentId,
    this.contactId,
    DateTime? createdAt,
    DateTime? updatedAt,
  })  : createdAt = createdAt ?? DateTime.now(),
        updatedAt = updatedAt ?? DateTime.now();

  factory ActionDraft.fromMap(Map<String, dynamic> map) {
    return ActionDraft(
      id: map['id'] as int?,
      type: DraftType.values.firstWhere(
        (e) => e.name == map['type'],
        orElse: () => DraftType.email,
      ),
      title: map['title'] as String,
      recipientName: map['recipient_name'] as String?,
      recipientContact: map['recipient_contact'] as String?,
      subject: map['subject'] as String?,
      body: map['body'] as String,
      status: DraftStatus.values.firstWhere(
        (e) => e.name == map['status'],
        orElse: () => DraftStatus.draft,
      ),
      commitmentId: map['commitment_id'] as int?,
      contactId: map['contact_id'] as int?,
      createdAt: DateTime.parse(map['created_at'] as String),
      updatedAt: DateTime.parse(map['updated_at'] as String),
    );
  }

  Map<String, dynamic> toMap() {
    return {
      if (id != null) 'id': id,
      'type': type.name,
      'title': title,
      'recipient_name': recipientName,
      'recipient_contact': recipientContact,
      'subject': subject,
      'body': body,
      'status': status.name,
      'commitment_id': commitmentId,
      'contact_id': contactId,
      'created_at': createdAt.toIso8601String(),
      'updated_at': updatedAt.toIso8601String(),
    };
  }

  ActionDraft copyWith({
    int? id,
    DraftType? type,
    String? title,
    String? recipientName,
    String? recipientContact,
    String? subject,
    String? body,
    DraftStatus? status,
    int? commitmentId,
    int? contactId,
    DateTime? createdAt,
    DateTime? updatedAt,
  }) {
    return ActionDraft(
      id: id ?? this.id,
      type: type ?? this.type,
      title: title ?? this.title,
      recipientName: recipientName ?? this.recipientName,
      recipientContact: recipientContact ?? this.recipientContact,
      subject: subject ?? this.subject,
      body: body ?? this.body,
      status: status ?? this.status,
      commitmentId: commitmentId ?? this.commitmentId,
      contactId: contactId ?? this.contactId,
      createdAt: createdAt ?? this.createdAt,
      updatedAt: updatedAt ?? DateTime.now(),
    );
  }
}
